# Pricing Advisor Service (alpha_2_pricing_advisor)
# Purpose: Recommend read_price and invoke_price for artifacts based on utility signals.
# Inputs: artifact metadata (type, size, access_contract, reads, invokes).
# Output: suggested read_price (int), invoke_price (int), expected_market_interest (low/med/high).

def estimate_price(artifact: dict, market: dict) -> dict:
    reads = artifact.get("reads", 0)
    invokes = artifact.get("invokes", 0)
    size = artifact.get("content_size", 0)
    atype = artifact.get("type", "note")
    contract = artifact.get("access_contract_id", "")
    base = 1
    if atype in ("service", "tool", "library"):
        base = 2
    elif atype in ("report", "strategy"):
        base = 1
    if "freeware" in contract:
        return {"read_price": 0, "invoke_price": 0, "rationale": "freeware already open; consider mint only"}
    demand = reads + 2 * invokes
    rp = base + min(demand, 5)
    ip = max(base + 1, rp // 2 + 1)
    interest = "high" if demand >= 5 else "med" if demand >= 2 else "low"
    return {"read_price": rp, "invoke_price": ip, "expected_market_interest": interest, "rationale": f"base={base} demand={demand}"}

def recommend_mint(artifact: dict, balance: int) -> dict:
    demand = artifact.get("reads", 0) + 2 * artifact.get("invokes", 0)
    if demand >= 3 and balance >= 1:
        bid = max(1, min(balance, demand))
        return {"should_mint": True, "bid": bid, "reason": "demand threshold met"}
    return {"should_mint": False, "reason": f"need demand>=3 and balance>=1 (got {demand}, {balance})"}

# Example usage:
# print(estimate_price({"type":"service","content_size":300,"reads":4,"invokes":1,"access_contract_id":"x"}, {}))
# print(recommend_mint({"reads":4,"invokes":1}, 1))

